// Pep Lab: one small single-page app, no framework, no build step.
//
// How it works:
//   - The URL hash is the route: #/ (analyse), #/a/<id> (a result), #/players, #/calibrate, #/health.
//   - Each route is a function that fetches what it needs from the API and sets innerHTML.
//   - Everything user-supplied goes through esc() before it touches HTML (no injected scripts).
//   - Icons come from icons.js, generated by scripts/build_brand.py, drawn with currentColor.

import { ICONS, MARK } from "/assets/icons.js";

const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => [...root.querySelectorAll(sel)];
const app = $("#app");
let meta = null;
let timers = [];
let jumpToRate = false; // set by the Calibrate page: open a result scrolled to its rating form

// ---------------------------------------------------------------- helpers

const esc = (s) =>
  String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);

const icon = (name, cls = "") =>
  `<svg class="${cls}" viewBox="0 0 40 40" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(ICONS[name] || ICONS.ball).map((d) => `<path d="${d}"/>`).join("")}</svg>`;

const markSvg = (color) => `<svg viewBox="0 0 185 196" fill="${color}" aria-hidden="true">${MARK}</svg>`;

async function api(path, opts = {}) {
  const res = await fetch(path, opts);
  if (!res.ok) {
    let msg = `${res.status}`;
    try { msg = (await res.json()).detail || msg; } catch {}
    throw new Error(typeof msg === "string" ? msg : JSON.stringify(msg));
  }
  return res.json();
}

function toast(text) {
  const t = $("#toast");
  t.textContent = text;
  t.classList.add("show");
  setTimeout(() => t.classList.remove("show"), 2600);
}

const kmh = (ms) => (ms == null ? "–" : (ms * 3.6).toFixed(1));
const ago = (iso) => {
  if (!iso) return "";
  const s = (Date.now() - new Date(iso).getTime()) / 1000;
  if (s < 60) return "just now";
  if (s < 3600) return `${Math.round(s / 60)} min ago`;
  if (s < 86400) return `${Math.round(s / 3600)} h ago`;
  return new Date(iso).toLocaleDateString();
};
const initials = (name) => esc((name || "?").split(/\s+/).map((w) => w[0]).join("").slice(0, 2).toUpperCase());

// ---------------------------------------------------------------- router

const routes = [
  [/^#?\/?$/, pageAnalyse, "analyse"],
  [/^#\/a\/([\w-]+)$/, pageResult, "analyse"],
  [/^#\/players$/, pagePlayers, "players"],
  [/^#\/calibrate$/, pageCalibrate, "calibrate"],
  [/^#\/health$/, pageHealth, "health"],
];

const NAV = [
  ["analyse", "#/", "upload", "Analyse"],
  ["players", "#/players", "eye", "Players"],
  ["calibrate", "#/calibrate", "target", "Calibrate"],
  ["health", "#/health", "pulse", "Health"],
];

async function route() {
  timers.forEach(clearInterval);
  timers = [];
  const hash = location.hash || "#/";
  for (const [re, page, tab] of routes) {
    const m = hash.match(re);
    if (m) {
      $("#nav").innerHTML = NAV.map(
        ([key, href, ic, label]) => `<a href="${href}" class="${key === tab ? "on" : ""}">${icon(ic)}<span>${label}</span></a>`,
      ).join("");
      window.scrollTo(0, 0);
      try {
        await page(...m.slice(1));
      } catch (e) {
        app.innerHTML = `<div class="empty">${icon("whistle")}<h2>That didn't work</h2><p>${esc(e.message)}</p></div>`;
      }
      return;
    }
  }
  location.hash = "#/";
}

// ---------------------------------------------------------------- Analyse (upload)

const form = { file: null, positions: new Set(), clipType: "match", drill: "", target: null, targetAt: 0, cones: [] };

async function pageAnalyse() {
  const recent = await api("/lab/analyses?limit=6&source=lab");
  app.innerHTML = `
    <section class="hero fade-in">
      <span class="eyebrow neon">Pep · Tracka's AI coach</span>
      <h1>Read the game.<br/>Rate the <span class="hl">player</span>.</h1>
      <p>Drop in a clip. Pep follows the player, measures their speed, touches and body shape, scores them against their age group, and explains how to get better.</p>
      <div class="tape"></div>
    </section>

    <div class="grid cols-2">
      <div class="card stack fade-in" id="upload-card">
        <div class="drop" id="drop" tabindex="0" role="button" aria-label="Choose a clip">
          ${icon("upload")}
          <strong>Drop a clip here</strong>
          <span class="muted">MP4 or MOV · 3 seconds to 3 minutes · or click to choose</span>
        </div>
        <input type="file" id="file" accept="video/*" hidden />
        <div id="picker"></div>

        <div class="grid cols-2" style="grid-template-columns:1fr 1fr">
          <label class="field"><span>Player name</span><input type="text" id="label" placeholder="e.g. Kofi Mensah" maxlength="80" /></label>
          <label class="field"><span>Age</span><input type="number" id="age" min="6" max="60" placeholder="16" /></label>
          <label class="field"><span>Height (m)</span><input type="number" id="height" min="1" max="2.3" step="0.01" placeholder="1.75" /></label>
          <label class="field"><span>Plays in</span>
            <select id="sex"><option value="">Not set</option><option value="male">Boys' / men's</option><option value="female">Girls' / women's</option></select>
          </label>
        </div>

        <label class="field"><span>Positions</span><div class="chips" id="positions"></div></label>

        <label class="field"><span>What kind of clip</span>
          <div class="seg" id="cliptype">
            ${["match", "training", "drill", "highlight"].map((t) => `<button type="button" data-v="${t}" class="${form.clipType === t ? "on" : ""}">${t[0].toUpperCase() + t.slice(1)}</button>`).join("")}
          </div>
        </label>
        <div id="drill-box"></div>

        <button class="btn block" id="go" disabled>${icon("bolt")} Analyse clip</button>
      </div>

      <div class="stack fade-in">
        <div class="card neon">
          <span class="eyebrow">How Pep reads a clip</span>
          <ol style="margin:12px 0 0;padding-left:20px;display:grid;gap:8px;font-weight:500">
            <li>Finds every person, their body points and the ball (YOLO26)</li>
            <li>Cancels the camera's panning, picks your player, follows them</li>
            <li>Turns pixels into metres, smooths the path (Kalman filter)</li>
            <li>Measures speed, touches, body shape; times drills</li>
            <li>Scores against the age group; Gemini adds coaching notes</li>
          </ol>
          ${icon("ball", "accent")}
        </div>
        <div class="card">
          <div class="row spread"><h3>Recent</h3><a href="#/players" class="faint" style="font-size:13px;font-weight:700">All players →</a></div>
          <div class="stack" style="margin-top:12px">
            ${recent.length ? recent.map(rowMini).join("") : `<p class="muted" style="margin:0">Nothing analysed yet. Your first clip will show up here.</p>`}
          </div>
        </div>
      </div>
    </div>`;

  $("#positions").innerHTML = meta.positions
    .map((p) => `<button type="button" class="chip-btn ${form.positions.has(p) ? "on" : ""}" data-p="${p}">${p}</button>`)
    .join("");
  $$("#positions .chip-btn").forEach((b) =>
    b.addEventListener("click", () => {
      form.positions.has(b.dataset.p) ? form.positions.delete(b.dataset.p) : form.positions.add(b.dataset.p);
      b.classList.toggle("on");
    }),
  );
  $$("#cliptype button").forEach((b) =>
    b.addEventListener("click", () => {
      form.clipType = b.dataset.v;
      $$("#cliptype button").forEach((x) => x.classList.toggle("on", x === b));
      renderDrillBox();
      renderPicker();
    }),
  );
  $$("[data-job]").forEach((el) => el.addEventListener("click", () => (location.hash = `#/a/${el.dataset.job}`)));

  const drop = $("#drop");
  const file = $("#file");
  drop.addEventListener("click", () => file.click());
  drop.addEventListener("keydown", (e) => (e.key === "Enter" || e.key === " ") && file.click());
  drop.addEventListener("dragover", (e) => { e.preventDefault(); drop.classList.add("over"); });
  drop.addEventListener("dragleave", () => drop.classList.remove("over"));
  drop.addEventListener("drop", (e) => { e.preventDefault(); drop.classList.remove("over"); choose(e.dataTransfer.files[0]); });
  file.addEventListener("change", () => choose(file.files[0]));
  $("#go").addEventListener("click", submit);
  renderDrillBox();
}

function rowMini(j) {
  return `<div class="row" data-job="${j.id}" style="cursor:pointer">
    <div class="avatar">${initials(j.player)}</div>
    <div style="flex:1;min-width:0"><div style="font-weight:700">${esc(j.player)}</div>
      <div class="faint" style="font-size:12.5px">${esc(j.topRole || j.positions.join(", ") || j.clipType)} · ${ago(j.createdAt)}</div></div>
    ${j.status === "READY" ? `<span class="kit" style="--size:30px">${j.overallScore ?? "–"}</span>` : `<span class="pill ${j.status}">${j.status}</span>`}
  </div>`;
}

function renderDrillBox() {
  const box = $("#drill-box");
  if (!box) return;
  if (form.clipType !== "drill") { box.innerHTML = ""; form.drill = ""; return; }
  const drills = meta.drills;
  if (!form.drill) form.drill = Object.keys(drills)[0];
  box.innerHTML = `
    <label class="field"><span>Which drill</span>
      <select id="drill">${Object.entries(drills).map(([k, d]) => `<option value="${k}" ${k === form.drill ? "selected" : ""}>${esc(d.label)}</option>`).join("")}</select>
    </label>
    <div class="skill" style="margin-top:10px"><div class="drill">${icon("cone")}<span>${esc(drills[form.drill].how)}</span></div></div>`;
  $("#drill").addEventListener("change", (e) => { form.drill = e.target.value; form.cones = []; renderDrillBox(); renderPicker(); });
}

function choose(f) {
  if (!f) return;
  form.file = f;
  form.target = null;
  form.cones = [];
  $("#drop").innerHTML = `${icon("check")}<strong>${esc(f.name)}</strong><span class="muted">${(f.size / 1048576).toFixed(1)} MB · click to change</span>`;
  renderPicker();
  $("#go").disabled = false;
}

// Tap the player (and, for drills, the cones) on a paused frame of the clip.
function renderPicker() {
  const box = $("#picker");
  if (!box || !form.file) return;
  const needsCones = form.clipType === "drill" && meta.drills[form.drill]?.needs_calibration;
  const cones = needsCones ? meta.drills[form.drill].cones_m : [];
  const url = URL.createObjectURL(form.file);
  const stepText = () => {
    if (needsCones && form.cones.length < cones.length) {
      const [x, y] = cones[form.cones.length];
      return `Tap cone ${form.cones.length + 1} of ${cones.length}: the one at ${x} m along, ${y} m across.`;
    }
    return form.target ? "Got you. Tap again to move the marker, or scrub to another moment." : "Pause where you're clearly visible, then tap yourself.";
  };
  box.innerHTML = `<div class="frame-pick" id="fp"><video src="${url}" muted playsinline controls preload="metadata"></video><div class="hint" id="fp-hint">${stepText()}</div></div>`;
  const fp = $("#fp");
  const video = $("video", fp);
  const draw = () => {
    $$(".pin", fp).forEach((p) => p.remove());
    form.cones.forEach((c, i) => fp.insertAdjacentHTML("beforeend", `<div class="pin cone" style="left:${c.x * 100}%;top:${(c.y * video.clientHeight) / fp.clientHeight * 100}%">${i + 1}</div>`));
    if (form.target) fp.insertAdjacentHTML("beforeend", `<div class="pin" style="left:${form.target.x * 100}%;top:${(form.target.y * video.clientHeight) / fp.clientHeight * 100}%"></div>`);
    $("#fp-hint").textContent = stepText();
  };
  video.addEventListener("click", (e) => {
    const r = video.getBoundingClientRect();
    // Ignore taps on the native controls strip at the bottom.
    if (e.clientY > r.bottom - 44) return;
    e.preventDefault();
    video.pause();
    const p = { x: (e.clientX - r.left) / r.width, y: (e.clientY - r.top) / r.height };
    if (needsCones && form.cones.length < cones.length) {
      form.cones.push(p);
      form.conesAt = video.currentTime;
    } else {
      form.target = p;
      form.targetAt = video.currentTime;
    }
    draw();
  });
}

async function submit() {
  const btn = $("#go");
  const needsCones = form.clipType === "drill" && meta.drills[form.drill]?.needs_calibration;
  if (needsCones && form.cones.length < meta.drills[form.drill].cones_m.length) {
    toast("Tap all the cones on the frame first");
    return;
  }
  const req = {
    positions: [...form.positions],
    clipType: form.clipType,
    playerLabel: $("#label").value.trim() || undefined,
    ageYears: +$("#age").value || undefined,
    playerHeightM: +$("#height").value || undefined,
    sex: $("#sex").value || undefined,
  };
  if (form.clipType === "drill") req.drill = form.drill;
  if (form.target) { req.target = form.target; req.targetAtSeconds = form.targetAt; }
  if (needsCones) {
    req.calibration = { atSeconds: form.conesAt || 0, imagePoints: form.cones, worldPointsM: meta.drills[form.drill].cones_m };
  }
  const body = new FormData();
  body.append("video", form.file);
  body.append("request", JSON.stringify(req));
  btn.disabled = true;
  btn.innerHTML = `${icon("refresh", "spinner")} Uploading…`;
  try {
    const { id } = await api("/lab/clips", { method: "POST", body });
    form.file = null; form.target = null; form.cones = [];
    location.hash = `#/a/${id}`;
  } catch (e) {
    toast(e.message);
    btn.disabled = false;
    btn.innerHTML = `${icon("bolt")} Analyse clip`;
  }
}

// ---------------------------------------------------------------- Result

const STEPS = ["Queued", "Finding the player", "Measuring", "Scoring", "Coach notes"];

async function pageResult(id) {
  const job = await api(`/lab/analyses/${id}`);
  if (job.status === "QUEUED" || job.status === "RUNNING") return renderWaiting(job);
  if (job.status === "FAILED") return renderFailed(job);
  renderResult(job);
}

function renderWaiting(job) {
  const started = Date.now();
  app.innerHTML = `
    <section class="hero fade-in" style="place-items:center;text-align:center;padding-top:90px">
      ${icon("ball", "spinner")}
      <h2>Pep is watching ${esc(job.player)}'s clip</h2>
      <p class="muted" id="wait-text">${job.status === "QUEUED" ? "Waiting for a free worker…" : "Analysing…"}</p>
      <div class="progress-steps" id="steps">${STEPS.map((s, i) => `<span class="${i === 0 ? "on" : ""}">${s}</span>`).join("")}</div>
    </section>`;
  // We don't stream progress from the worker; the steps advance on a rough clock so the wait feels alive.
  timers.push(
    setInterval(async () => {
      const elapsed = (Date.now() - started) / 1000;
      const step = Math.min(STEPS.length - 1, Math.floor(elapsed / 6));
      $$("#steps span").forEach((s, i) => s.classList.toggle("on", i <= step));
      const now = await api(`/lab/analyses/${job.id}`).catch(() => null);
      if (now && !["QUEUED", "RUNNING"].includes(now.status)) route();
      else if (now) $("#wait-text").textContent = now.status === "QUEUED" ? "Waiting for a free worker…" : `Analysing… ${Math.round(elapsed)} s`;
    }, 2000),
  );
}

function renderFailed(job) {
  app.innerHTML = `
    <div class="empty fade-in">
      ${icon("whistle")}
      <h2>Pep couldn't score this clip</h2>
      <p style="max-width:440px">${esc(job.error || "Something went wrong.")}</p>
      <a class="btn" href="#/">${icon("upload")} Try another clip</a>
    </div>`;
}

function renderResult(job) {
  const r = job.result;
  const m = r.metrics || {};
  const skills = r.skills || [];
  // Player's own positions first, so "best fit" is a role they actually play.
  const mine = (f) => f.coverage >= 0.35 && job.positions.some((p) => meta.roles[f.role]?.positions.includes(p));
  const roles = [...(r.roleFit || [])].sort((a, b) => mine(b) - mine(a) || b.score - a.score);
  const moments = r.moments || [];
  const len = Math.max(job.request.lengthSeconds || 0, ...moments.map((x) => x.atSeconds + 1), m.seconds_tracked || 0, 1);

  const metricTiles = [
    ["Top speed", kmh(m.top_speed_ms), "km/h"],
    ["Distance", m.distance_m ?? "–", "m"],
    ["Peak accel", m.peak_accel_ms2 ?? "–", "m/s²"],
    ["High-speed runs", m.high_speed_runs ?? "–", ""],
    ["Touches / min", m.touches_per_min ?? "–", ""],
    ["Sharp turns / min", m.turns_per_min ?? "–", ""],
    ["30 m sprint", m.sprint_30m_s ?? null, "s"],
    ["10 m split", m.split_10m_s ?? null, "s"],
    ["5-10-5", m.agility_5105_s ?? null, "s"],
    ["Keepy-ups", m.juggles_best ?? null, ""],
    ["Dives", m.dives ?? null, ""],
  ].filter(([, v]) => v !== null);

  app.innerHTML = `
    <section class="hero fade-in" style="padding-bottom:22px">
      <a href="#/players" class="row faint" style="text-decoration:none;font-weight:700;font-size:13px;width:max-content">${icon("back")} Players</a>
      <div class="row wrap spread" style="align-items:flex-end">
        <div class="stack" style="gap:8px">
          <span class="eyebrow neon">${esc(job.clipType)} · ${esc(job.positions.join(" / ") || "any position")} · ${ago(job.createdAt)}</span>
          <h1 style="font-size:clamp(36px,5.4vw,60px)">${esc(job.player)}</h1>
        </div>
        <div class="row">
          <span class="pill ${esc(r.confidence)}">${esc(r.confidence)} confidence</span>
          <span class="pill">${r.coachSource === "gemini" ? "AI coach notes" : "Rule-based notes"}</span>
        </div>
      </div>
    </section>

    <div class="grid cols-2">
      <div class="stack">
        <div class="player fade-in">
          <video id="vid" src="${esc(job.overlayUrl || job.videoUrl)}" controls playsinline preload="metadata"></video>
        </div>
        <div class="row spread">
          <div class="timeline" id="tl" style="flex:1">
            ${moments.map((x, i) => `<button class="${x.kind}" style="left:${Math.min(99, (x.atSeconds / len) * 100)}%" data-i="${i}" title="${esc(x.text)}"></button>`).join("")}
            <div class="head" id="head" style="left:0"></div>
          </div>
          ${job.overlayUrl ? `<button class="btn ghost small" id="swap">${icon("eye")} <span>Original</span></button>` : ""}
        </div>
        <div class="card stack">
          <h3>Moments</h3>
          ${moments.length ? moments.map((x, i) => `<div class="moment ${x.kind}" data-i="${i}"><span class="t">${x.atSeconds.toFixed(1)}s</span><span class="dot"></span><span>${esc(x.text)}</span></div>`).join("") : `<p class="muted" style="margin:0">No standout moments flagged in this clip.</p>`}
        </div>
      </div>

      <div class="stack">
        <div class="card neon fade-in">
          <div class="score-card">
            <span class="kit">${r.overallScore ?? "–"}</span>
            <div class="stack" style="gap:6px">
              <span class="eyebrow">Overall${roles[0] ? ` · best fit` : ""}</span>
              <b style="font:700 22px/1.1 var(--display);letter-spacing:-0.02em">${esc(roles[0]?.label || "Not enough of the role seen")}</b>
            </div>
          </div>
          ${r.summary ? `<div class="sep" style="background:rgba(10,11,9,.15);margin:16px 0"></div><p class="summary">${esc(r.summary)}</p>` : ""}
          ${icon("star", "accent")}
        </div>

        <div class="card stack">
          <div class="row spread"><h3>Role fit</h3><span class="faint" style="font-size:12px">for scouts</span></div>
          ${roles.slice(0, 5).map((f) => `
            <div class="role">
              <span style="font-weight:700">${esc(f.label)} <span class="faint" style="font-weight:500;font-size:12.5px">· saw ${Math.round(f.coverage * 100)}% of the role</span></span>
              <b>${f.score}</b>
              <div class="bar ${f.coverage < 0.35 ? "blue" : ""}"><i style="width:${f.score}%"></i></div>
            </div>`).join("") || `<p class="muted" style="margin:0">Not enough measured to fit a role.</p>`}
        </div>
      </div>
    </div>

    <h2 style="margin:38px 0 14px">Skills</h2>
    <div class="grid cols-3">
      ${skills.map((s) => `
        <div class="skill fade-in">
          <div class="top">
            <span class="kit">${s.score}</span>
            <div class="stack" style="gap:5px;flex:1">
              <span class="name">${esc(s.name)}</span>
              <div class="row" style="gap:6px"><span class="pill ${esc(s.source)}">${esc((s.source || "").replace("_", " "))}</span><span class="pill ${esc(s.confidence)}">${esc(s.confidence)}</span></div>
            </div>
          </div>
          <div class="bar"><i style="width:${s.score}%"></i></div>
          <p>${esc(s.explanation)}</p>
          ${s.drill ? `<div class="drill">${icon("cone")}<span>${esc(s.drill)}</span></div>` : ""}
        </div>`).join("")}
    </div>

    <h2 style="margin:38px 0 14px">Measurements</h2>
    <div class="grid cols-4">
      ${metricTiles.map(([k, v, u]) => `<div class="metric"><span class="eyebrow">${k}</span><span class="v">${esc(v)}<small>${u}</small></span></div>`).join("")}
    </div>

    <div class="grid cols-2" style="margin-top:38px">
      <div class="card stack" id="rate">
        <div class="row spread"><h3>Rate this clip</h3>${icon("target")}</div>
        <p class="muted" style="margin:0">Scouts and coaches: your rating teaches Pep. Score the player as you would on a scouting report.</p>
        <div class="grid" style="grid-template-columns:1fr 1fr;gap:12px">
          <label class="field"><span>Your name</span><input type="text" id="r-rater" maxlength="80" /></label>
          <label class="field"><span>For the role</span><select id="r-role"><option value="">Overall</option>${Object.entries(meta.roles).map(([k, v]) => `<option value="${k}">${esc(v.label)}</option>`).join("")}</select></label>
        </div>
        <label class="field"><span>Your score: <b class="hl" id="r-val">60</b></span><input type="range" id="r-overall" min="30" max="95" value="60" /></label>
        <label class="field"><span>Notes</span><textarea id="r-notes" rows="2" maxlength="1000"></textarea></label>
        <button class="btn" id="r-save">${icon("check")} Save rating</button>
        ${job.ratings.length ? `<div class="sep"></div>${job.ratings.map((x) => `<div class="row spread"><span><b>${esc(x.rater)}</b> <span class="faint">${esc(x.role ? meta.roles[x.role]?.label || x.role : "overall")}</span></span><span class="kit" style="--size:26px">${x.overall}</span></div>`).join("")}` : ""}
      </div>
      <div class="card stack">
        <h3>Under the hood</h3>
        <p class="muted" style="margin:0">Model ${esc(r.modelVersion)} · ${esc(m.seconds_tracked)} s tracked · player seen in ${Math.round((m.seen_share || 0) * 100)}% of frames · camera measured ${Math.round((m.camera_reliability || 0) * 100)}% of the time</p>
        ${Object.entries(job.timings || {}).filter(([k]) => k !== "total").map(([k, v]) => `
          <div class="stage"><span class="faint">${esc(k)}</span><div class="bar"><i style="width:${Math.min(100, (v / Math.max(job.timings.total || 1, 0.01)) * 100)}%"></i></div><span class="num">${(+v).toFixed(2)} s</span></div>`).join("")}
        <details><summary>Raw result (what Tracka receives)</summary><pre>${esc(JSON.stringify(r, null, 2))}</pre></details>
      </div>
    </div>`;

  const vid = $("#vid");
  const seek = (i) => { vid.currentTime = moments[i].atSeconds; vid.play(); };
  $$("#tl button, .moment").forEach((b) => b.addEventListener("click", () => seek(+b.dataset.i)));
  vid.addEventListener("timeupdate", () => { $("#head").style.left = `${Math.min(100, (vid.currentTime / len) * 100)}%`; });
  const swap = $("#swap");
  if (swap) {
    let showingOverlay = true;
    swap.addEventListener("click", () => {
      const t = vid.currentTime;
      showingOverlay = !showingOverlay;
      vid.src = showingOverlay ? job.overlayUrl : job.videoUrl;
      vid.currentTime = t;
      $("span", swap).textContent = showingOverlay ? "Original" : "What Pep saw";
    });
  }
  if (jumpToRate) {
    jumpToRate = false;
    $("#rate").scrollIntoView({ behavior: "smooth", block: "center" });
  }
  $("#r-overall").addEventListener("input", (e) => ($("#r-val").textContent = e.target.value));
  $("#r-save").addEventListener("click", async () => {
    const rater = $("#r-rater").value.trim();
    if (!rater) return toast("Add your name first");
    try {
      await api(`/lab/analyses/${job.id}/ratings`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ rater, overall: +$("#r-overall").value, role: $("#r-role").value || null, notes: $("#r-notes").value || null }),
      });
      toast("Rating saved. Thank you!");
      route();
    } catch (e) { toast(e.message); }
  });
}

// ---------------------------------------------------------------- Players (scout view)

async function pagePlayers() {
  const all = await api("/lab/analyses?limit=500");
  const state = { q: "", role: "", minConf: "LOW", sort: "score" };
  app.innerHTML = `
    <section class="hero fade-in" style="padding-bottom:20px">
      <span class="eyebrow neon">Scout view</span>
      <h1>Players</h1>
      <p>Every analysed clip. Filter by the role you're scouting for; scores re-rank by role fit.</p>
    </section>
    <div class="row wrap" style="margin-bottom:8px">
      <div style="flex:2;min-width:200px"><input type="text" id="q" placeholder="Search players" /></div>
      <div style="flex:1;min-width:180px"><select id="role"><option value="">Any role</option>${Object.entries(meta.roles).map(([k, v]) => `<option value="${k}">${esc(v.label)}</option>`).join("")}</select></div>
      <div style="flex:1;min-width:160px"><select id="conf"><option value="LOW">Any confidence</option><option value="MEDIUM">Medium or high</option><option value="HIGH">High only</option></select></div>
    </div>
    <div id="list"></div>`;

  const rank = { LOW: 0, MEDIUM: 1, HIGH: 2 };
  const render = () => {
    let rows = all.filter((j) => j.player.toLowerCase().includes(state.q) && rank[j.confidence || "LOW"] >= rank[state.minConf]);
    if (state.role) {
    }
    // With a role chosen, rank by fit for that role (only where Pep saw enough of it).
    const scoreOf = (j) => (state.role ? j.roles?.[state.role] : j.overallScore) ?? -1;
    if (state.role) rows = rows.filter((j) => j.roles?.[state.role] != null);
    rows.sort((a, b) => scoreOf(b) - scoreOf(a));
    $("#list").innerHTML = rows.length
      ? `<table class="table"><thead><tr><th>Player</th><th class="hide-sm">Clip</th><th class="hide-sm">Best fit</th><th>Confidence</th><th style="text-align:right">${state.role ? "Role fit" : "Score"}</th></tr></thead><tbody>
        ${rows.map((j) => `<tr class="link" data-job="${j.id}">
          <td><div class="row"><div class="avatar">${initials(j.player)}</div><div><div style="font-weight:700">${esc(j.player)}</div><div class="faint" style="font-size:12.5px">${esc(j.positions.join(" / ") || "—")}</div></div></div></td>
          <td class="hide-sm"><span class="muted">${esc(j.clipType)}</span><div class="faint" style="font-size:12px">${ago(j.createdAt)}</div></td>
          <td class="hide-sm">${esc(j.topRole || "—")}</td>
          <td>${j.status === "READY" ? `<span class="pill ${esc(j.confidence)}">${esc(j.confidence)}</span>` : `<span class="pill ${j.status}">${j.status}</span>`}</td>
          <td style="text-align:right">${scoreOf(j) >= 0 ? `<span class="kit">${scoreOf(j)}</span>` : "–"}</td></tr>`).join("")}
        </tbody></table>`
      : `<div class="empty">${icon("eye")}<h3>No players match</h3><p>Try a different role or confidence.</p></div>`;
    $$("[data-job]").forEach((el) => el.addEventListener("click", () => (location.hash = `#/a/${el.dataset.job}`)));
  };
  $("#q").addEventListener("input", (e) => { state.q = e.target.value.toLowerCase(); render(); });
  $("#role").addEventListener("change", (e) => { state.role = e.target.value; render(); });
  $("#conf").addEventListener("change", (e) => { state.minConf = e.target.value; render(); });
  render();
}

// ---------------------------------------------------------------- Calibrate (agreement with scouts)

async function pageCalibrate() {
  const [agree, all] = await Promise.all([api("/lab/agreement"), api("/lab/analyses?limit=200")]);
  const ready = all.filter((j) => j.status === "READY");
  const fmt = (v, d = 1) => (v == null ? "–" : (+v).toFixed(d));
  app.innerHTML = `
    <section class="hero fade-in" style="padding-bottom:20px">
      <span class="eyebrow neon">Calibration</span>
      <h1>Does Pep agree<br/>with <span class="hl">scouts</span>?</h1>
      <p>Scouts rate clips; Pep compares. These numbers are how you know if a model change made Pep better or worse. Aim for a gap of under 8 points and a rank match above 0.7.</p>
    </section>
    <div class="grid cols-4">
      <div class="card stat"><span class="eyebrow">Ratings</span><div class="v">${agree.n}</div><span class="faint">clips scouts have rated</span></div>
      <div class="card stat"><span class="eyebrow">Average gap</span><div class="v">${fmt(agree.mae)}</div><span class="faint">points between Pep and scouts</span></div>
      <div class="card stat"><span class="eyebrow">Rank match</span><div class="v">${fmt(agree.spearman, 2)}</div><span class="faint">Spearman, 1 = same order</span></div>
      <div class="card stat"><span class="eyebrow">Within 10</span><div class="v">${agree.within10 == null ? "–" : Math.round(agree.within10 * 100) + "%"}</div><span class="faint">${agree.bias == null ? "" : agree.bias > 0 ? `Pep is ${fmt(agree.bias)} pts generous` : `Pep is ${fmt(-agree.bias)} pts harsh`}</span></div>
    </div>
    <div class="row spread" style="margin:34px 0 12px"><h2>Clips to rate</h2><span class="faint">${ready.length} ready</span></div>
    <div class="grid cols-3">
      ${ready.slice(0, 30).map((j) => `<div class="card stack" data-job="${j.id}" style="cursor:pointer">
        <div class="row"><div class="avatar">${initials(j.player)}</div><div style="flex:1"><b>${esc(j.player)}</b><div class="faint" style="font-size:12.5px">${esc(j.clipType)} · ${ago(j.createdAt)}</div></div><span class="kit" style="--size:30px">${j.overallScore ?? "–"}</span></div>
        <span class="btn ghost small">${icon("star")} Rate</span></div>`).join("") || `<div class="empty">${icon("target")}<p>Analyse a few clips first.</p></div>`}
    </div>`;
  $$("[data-job]").forEach((el) =>
    el.addEventListener("click", () => {
      jumpToRate = true;
      location.hash = `#/a/${el.dataset.job}`;
    }),
  );
}

// ---------------------------------------------------------------- Health (the SRE view)

async function pageHealth() {
  const draw = async () => {
    const h = await api("/lab/health");
    const c = h.counts;
    const d = h.last24h;
    const s = (v) => (v == null ? "–" : `${v}`);
    const maxStage = Math.max(0.01, ...Object.entries(d.stagesMedian).filter(([k]) => k !== "total").map(([, v]) => v));
    app.innerHTML = `
      <section class="hero fade-in" style="padding-bottom:20px">
        <span class="eyebrow neon">Operations · refreshes every 10 s</span>
        <h1>Health</h1>
        <p>Is the queue keeping up, how long do clips take, what's failing. Model <b>${esc(h.version)}</b>.</p>
      </section>
      <div class="grid cols-4">
        <div class="card stat"><span class="eyebrow">Queued</span><div class="v">${c.QUEUED || 0}</div><span class="faint">oldest ${Math.round(h.oldestQueuedSeconds)} s</span></div>
        <div class="card stat"><span class="eyebrow">Running</span><div class="v">${c.RUNNING || 0}</div><span class="faint">on workers now</span></div>
        <div class="card stat"><span class="eyebrow">Done · 24 h</span><div class="v">${d.finished}</div><span class="faint">${d.failed} failed</span></div>
        <div class="card stat ${d.callbacksGaveUp ? "neon" : ""}"><span class="eyebrow">Callbacks lost</span><div class="v">${d.callbacksGaveUp}</div><span class="faint">results Tracka never got</span></div>
      </div>
      <div class="grid cols-2" style="margin-top:16px">
        <div class="card stack">
          <h3>Time per clip · last 24 h</h3>
          <div class="grid" style="grid-template-columns:1fr 1fr">
            <div class="metric"><span class="eyebrow">Wait p50 / p95</span><span class="v">${s(d.waitP50)}<small>s</small> / ${s(d.waitP95)}<small>s</small></span></div>
            <div class="metric"><span class="eyebrow">Run p50 / p95</span><span class="v">${s(d.runP50)}<small>s</small> / ${s(d.runP95)}<small>s</small></span></div>
          </div>
          <p class="faint" style="margin:0;font-size:13px">p95: 95% of clips were quicker than this. Tail latency is what players notice.</p>
        </div>
        <div class="card stack">
          <h3>Where the time goes (median)</h3>
          ${Object.entries(d.stagesMedian).filter(([k]) => k !== "total").map(([k, v]) => `
            <div class="stage"><span class="faint">${esc(k)}</span><div class="bar"><i style="width:${(v / maxStage) * 100}%"></i></div><span class="num">${v.toFixed(2)} s</span></div>`).join("") || `<p class="muted" style="margin:0">No finished clips yet.</p>`}
        </div>
      </div>`;
  };
  await draw();
  timers.push(setInterval(() => draw().catch(() => {}), 10000));
}

// ---------------------------------------------------------------- start

(async function start() {
  $("#brand-mark").innerHTML = markSvg("#0A0B09");
  meta = await api("/lab/meta");
  window.addEventListener("hashchange", route);
  route();
})();
